tiles.exec:
nvidia-smi --query-gpu=index,name,temperature.gpu,utilization.gpu,memory.used,memory.total,power.draw --format=csv,noheader,nounits | awk -F', *' '
function num(x) { return x ~ /^[0-9]+(\.[0-9]+)?$/ }
function add(s) { printf "%s%s", (n++ ? "," : ""), s }
BEGIN { printf "[" }
{
  g = $2; gsub(/NVIDIA |GeForce |["\\]/, "", g)
  if (num($3)) add(sprintf("{\"id\":\"gpu%s_temp\",\"name\":\"%s temp\",\"type\":\"gauge\",\"value\":%s,\"unit\":\"celsius\",\"max\":100,\"warn\":80,\"bad\":90,\"icon\":\"thermometer\",\"history\":true}", $1, g, $3))
  if (num($4)) add(sprintf("{\"id\":\"gpu%s_util\",\"name\":\"%s load\",\"type\":\"gauge\",\"value\":%s,\"unit\":\"percent\",\"alerts\":false,\"history\":true}", $1, g, $4))
  if (num($5) && num($6) && $6 > 0) add(sprintf("{\"id\":\"gpu%s_mem\",\"name\":\"%s memory\",\"type\":\"gauge\",\"value\":%.0f,\"max\":%.0f,\"unit\":\"bytes\",\"icon\":\"memory\"}", $1, g, $5 * 1048576, $6 * 1048576))
  if (num($7)) add(sprintf("{\"id\":\"gpu%s_power\",\"name\":\"%s power\",\"type\":\"number\",\"value\":%s,\"unit\":\"watts\",\"icon\":\"bolt\"}", $1, g, $7))
}
END { print "]" }'
